head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00201.xml";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {

    scwin.init();

};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 *  라디오 버튼 클릭시 화면명 설정 처리
 */
scwin.rdo_fg_onchange = function (info) {
	scwin.rdoFgOnSelChange();
};

/**
 *  기업현황 화면별 정보 조회
 */
scwin.btn_search_onclick = function() {
    scwin.search();
};

/**
 *  기업검색 팝업 호출
 */
scwin.img_coSearch_onclick = function() {
    scwin.comSrchOpen();
};

/**
 *  기업명 입력후 키다운 이벤트 처리
 */
scwin.ibx_coSnm_onkeydown = function (e) {

    if (e.keyCode === 13) {

        if (ibx_coSnm.getValue() === "") {
            // 기업검색팝업 오픈
            scwin.comSrchOpen();
        } else {
            // 기업정보 조회
            scwin.comInfoSrch();
        }
    }

};

/**
 *  결산일자 항목이 변경되면 기업정보 재조회
 */
scwin.sbx_acntclsDt_onchange = function (info) {

    // 기업현황 조회
    scwin.search();

};

/**
 *  기간 선택시 이벤트 처리
 */
scwin.sbx_periodTp_onchange = function (info) {

    let vTp = $c.cp.valueOfIndex(sbx_periodTp, "VALUE", sbx_periodTp.getSelectedIndex());

    if (vTp !== '0') {
        $c.stf.setFromToDate(vTp, ica_acntclsStrtDt, ica_acntclsEndDt);
    }

};

/**
 *  엑셀 다운로드 버튼 처리
 */
scwin.btn_excel_onclick = function (e) {

    if ($p.parent().frame_body.getWindow().scwin.fn_excel_download) {
        $p.parent().frame_body.getWindow().scwin.fn_excel_download();
    }

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 *  기업 정보 데이터 로드시 기능 처리(기업명으로 조회)
 */
scwin.sbm_comInfo_submitdone = function (e) {

    dlt_comListRes.setJSON(e.responseJSON.body);

    if (dlt_comListRes.getRowCount() === 1) {

        // 조회조건에 값을 세팅
        ibx_kisCd.setValue(dlt_comListRes.getCellData(0, "kisCd"));

        // 결산일자 visible = true인 경우
        if (pnl_acntclsDt.getStyle("display") === "none" || pnl_acntclsDt1.getStyle("display") === "none") {
            // 기업현황 조회
            scwin.search();
        } else {
            // 결산일자 조회
            if (pnl_acntclsDt.getStyle("display") !== "none") {
                scwin.srchAcntclsDt();
            }
        }
    } else {

        scwin.comSrchOpen(); //기업검색 팝업 오픈

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {

    //라디오 기본값 : 사업목적
    rdo_fg.setValue("02");

    // rdo_fg 값에따른 화면 처리
    scwin.rdoFgOnSelChange();

};

/**
 *  조회조건 기업현황 조회조건 값이 변동될때 로직 처리
 */
scwin.rdoFgOnSelChange = function() {

    const pageNum = rdo_fg.getValue();

    if (pageNum === "09" || pageNum === "10" || pageNum === "13") {
        btn_excel.hide();
    } else {
        btn_excel.show();
    }

    // 라디오 클릭 시 하단 프레임에 적당한 화면 세팅.
    scwin.displayFrame(rdo_fg.getValue());

    // 결산일자 visible
    scwin.displayAcntclsDt();

};

/**
 *  하단 frame에 출력 그리드 설정
 */
scwin.displayFrame = function(pVal) {

    $p.parent().frame_body.setSrc(scwin.getUrl(pVal));

};

/**
 *  프로그램 파일명 경로 설정
 */
scwin.getUrl = function(pVal) {

    const vUrl = "/ui/lst/fis/ULDFIS002" + pVal + ".xml";
    return vUrl;

};

/**
 * 결산일자 콤보박스 display 설정(보이기/숨김)
 */
scwin.displayAcntclsDt = function() {

    // 주요주주, 배당, 경영진구성
    if (rdo_fg.getValue() === "04" || rdo_fg.getValue() === "07" || rdo_fg.getValue() === "19") {

        pnl_acntclsDt1.setStyle("display", "");
        pnl_acntclsDt.setStyle("display", "none");

        //  기간 시작일자/종료일자 설정
        let vCurDate = $c.utils.cGetToday("yyyymmdd");
        ica_acntclsEndDt.setValue(vCurDate); // 현재날짜
        ica_acntclsStrtDt.setValue($c.date.addDate(vCurDate, -365));
        $c.stf.comboCbDataSetPeriod(sbx_periodTp);

    } else if (rdo_fg.getValue() === "06" || rdo_fg.getValue() === "08" || rdo_fg.getValue() === "09" ||
               rdo_fg.getValue() === "10" || rdo_fg.getValue() === "12" || rdo_fg.getValue() === "13" ||
               rdo_fg.getValue() === "14" || rdo_fg.getValue() === "15" || rdo_fg.getValue() === "16" ||
               rdo_fg.getValue() === "18" || rdo_fg.getValue() === "20" || rdo_fg.getValue() === "21") {

        pnl_acntclsDt.setStyle("display", "");
        pnl_acntclsDt1.setStyle("display", "none");

    } else {

        pnl_acntclsDt.setStyle("display", "none");
        pnl_acntclsDt1.setStyle("display", "none");

    }

};

/**
 *  결산일자 조회
 */
scwin.srchAcntclsDt = async function() {

    //데이터셋 초기화
    scwin.initDs("2");
    dlt_acntclsDtListRes.setData([]);

    // 결산일자 visible = true인 경우만 조회, KisCd 필수
    if (pnl_acntclsDt.getStyle("display") === "none" || ibx_kisCd.getValue() === "") {
        return;
    }

    dma_acntclsDtInfoReq.set("kisCd", ibx_kisCd.getValue()); // 기업코드

    switch (rdo_fg.getValue()) {
        case "08":
            dma_acntclsDtInfoReq.set("fg", "07"); // 종업원현황
            break;       
        case "09":
            dma_acntclsDtInfoReq.set("fg", "08"); // 업계현황
            break;     
        case "10":
            dma_acntclsDtInfoReq.set("fg", "09"); // 회사현황
            break;  
        case "13":
            dma_acntclsDtInfoReq.set("fg", "12"); // 판매경로
            break;
        case "14":
            dma_acntclsDtInfoReq.set("fg", "13"); // 제품및사업구성
            break;  
        case "15":
            dma_acntclsDtInfoReq.set("fg", "14"); // 주요제품가격동향
            break;    
        case "16":
            dma_acntclsDtInfoReq.set("fg", "15"); // 주요원재료가격동향
            break;                                                              
        case "18":
            dma_acntclsDtInfoReq.set("fg", "17"); // 장단기차입금현황
            break;
        default:
            dma_acntclsDtInfoReq.set("fg", rdo_fg.getValue()); // 기업현황코드
            break;
    }

    const sbmOptions = {
        id : "sbm_acntclsDt",
        action : "/api/listing/nice/company-status/acntclsdt",
        method : "get",
        ref : "dma_acntclsDtInfoReq",
        target : "dlt_acntclsDtListRes|append",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_acntclsDtListRes.setJSON(res.responseJSON.body);

    if (dlt_acntclsDtListRes.getRowCount() <= 0) {
        alert("결산일자가 존재하지 않습니다.");
    }

};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    //필수항목 체크
    if (ibx_coSnm.getValue() === "") {
        alert("기업명을 입력하세요.");
        ibx_coSnm.focus();
        return false;
    }

    if (pnl_acntclsDt.getStyle("display") !== "none" && (sbx_acntclsDt.getValue() === "" || sbx_acntclsDt.getValue() === null)) {
        alert("결산일자를 입력하세요.");
        sbx_acntclsDt.focus();
        return false;
    }

    if (pnl_acntclsDt1.getStyle("display") !== "none") {

        if (!$c.stf.compareFromToDate2(ica_acntclsStrtDt, ica_acntclsEndDt)) {
            return false;
        }

        if (ica_acntclsStrtDt.getValue() === "") {
            alert("기간 시작일를 입력하세요.");
            return false;
        }

        if (ica_acntclsEndDt.getValue() === "") {
            alert("기간 종료일를 입력하세요.");
            return false;
        }

    }

    // 기업명은 있는데 기업코드가 없는 경우
    if (ibx_coSnm.getValue() !== "" && ibx_kisCd.getValue() === "") {
        scwin.comInfoSrch();
        return false;
    }

    return true;
};

/**
 * 기업현황 조회
 */
scwin.search = function() {

    // 조회조건 필수 체크
    if (!scwin.chkValid()) {
        return;
    }

    if (rdo_fg.getValue() === "08" || rdo_fg.getValue() === "18") {
        scwin.getGrdHeaderNm();
    }

    if ($p.parent().frame_body.getWindow().scwin.search) {
        $p.parent().frame_body.getWindow().scwin.search();
    }

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function(pFg) {

    if (pFg === "1") {
        dlt_comListRes.setData([]);
    } else if (pFg === "2") {
        dlt_acntclsDtListRes.setData([]);
    }

};

/**
 * 기업정보 조회(명으로 조회)
 */
scwin.comInfoSrch = async function() {

    //데이터셋 초기화
    scwin.initDs("1");

    //기업명 없으면 중지.
    if (ibx_coSnm.getValue() === "") {
        return;
    }

    dma_comInfoReq.set("coSnm", ibx_coSnm.getValue()); // 기업명
    const sbmOptions = {
        id : "sbm_comInfo",
        action : "/api/listing/nice/com-overview/com-info",
        method : "get",
        ref : "dma_comInfoReq",
        target : "dlt_comListRes|append",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);    
    scwin.sbm_comInfo_submitdone(sbmRtn);

};

/**
 * 기업검색 팝업 화면을 표시한다.
 */
scwin.comSrchOpen = async function() {

    const url = "/ui/lst/fis/ULDFIS00101.xml";
    const popTitle = "기업 검색";

    const opts = {
        id: "ULDFIS00101",
        popupName: popTitle,
        width: 750,
        height: 490,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts);

    ibx_coSnm.setValue(res.coSnm); // 기업명
    ibx_kisCd.setValue(res.kisCd); // 기업코드

    if (ibx_kisCd.getValue() !== "" || ibx_kisCd.getValue() !== null) {

        // 결산일자 visible = true인 경우
        if (pnl_acntclsDt.getStyle("display") === "none" && pnl_acntclsDt1.getStyle("display") === "none") {
            // 기업현황 조회
            scwin.search();
        } else {
            // 결산일자 조회
            if (pnl_acntclsDt.getStyle("display") !== "none") {
                scwin.srchAcntclsDt();
            }
        }

    }

};

/**
 * 팝업으로 값을 전송
 */
scwin.getParKisCd = function() {

    const arrPar = new Array();
    arrPar[0] = ibx_coSnm.getValue(); // 기업명

    return arrPar;

};

/**
 *  조회조건의 기업코드를 리턴
 */
scwin.getKisCd = function() {
    return ibx_kisCd.getValue();
};

/**
 *  조회조건의 결산일자를 리턴
 */
scwin.getAcntclsDt = function() {
    return sbx_acntclsDt.getValue();
};

/**
 *  조회조건의 시작일자를 리턴
 */
scwin.getAcntclsStrtDt = function() {
    return ica_acntclsStrtDt.getValue();
};

/**
 *  조회조건의 종료일자를 리턴
 */
scwin.getAcntclsEndDt = function() {
    return ica_acntclsEndDt.getValue();
};

/**
 *  그리드 헤더 명을 구한다.
 */
scwin.getGrdHeaderNm = function() {

    if ( $p.parent().frame_body.getWindow().scwin.fn_SetGrdHeaderNm ) {

        let nCurrRow = sbx_acntclsDt.getSelectedIndex();
        let nTrgtRow = 0;

        if (rdo_fg.getValue() === "08" ) {
            nTrgtRow = nCurrRow + 3; // 종업원현황
        } else {
            nTrgtRow = nCurrRow + 2;
        }

        let aArray = new Array();
        let nArrRow = 0;

        for (let nRow = nCurrRow; nRow <= nTrgtRow; nRow++) {
            aArray[nArrRow] = {
                value: dlt_acntclsDtListRes.getCellData(nRow, "value"),
                text: dlt_acntclsDtListRes.getCellData(nRow, "text")
            };
            nArrRow++;
        }

        // 그리드 헤더 호출
        $p.parent().frame_body.getWindow().scwin.fn_SetGrdHeaderNm(aArray);

    }

};
